<?php $materials = is_array($materials ?? null) ? $materials : []; $sources = is_array($sources ?? null) ? $sources : []; $signals = is_array($signals ?? null) ? $signals : []; ?>
<section class="page-header"><div><p class="eyebrow">Content provenance</p><h1>Study Library</h1><p>Manage structured study materials, source references, and exam-specific editorial focus.</p></div></section>
<section class="ui-metric-grid"><article class="card stat-card"><span class="stat-label">Published materials</span><strong class="stat-value"><?= count($materials) ?></strong></article><article class="card stat-card"><span class="stat-label">Registered sources</span><strong class="stat-value"><?= count($sources) ?></strong></article><article class="card stat-card"><span class="stat-label">Intelligence signals</span><strong class="stat-value"><?= count($signals) ?></strong></article><article class="card stat-card"><span class="stat-label">Validation</span><strong class="stat-value"><?= (($sourceValidation['valid'] ?? false) && ($materialValidation['valid'] ?? false) && ($intelligenceValidation['valid'] ?? false)) ? 'Pass' : 'Review' ?></strong></article></section>
