<section><div class="section-heading"><div><p class="eyebrow">Registry</p><h2>Sources</h2></div></div><div class="record-list"><?php foreach ($sources as $source): ?><article class="card record-card"><div><h3><?= htmlspecialchars((string) ($source['title'] ?? '')) ?></h3><p><?= htmlspecialchars((string) ($source['authority'] ?? '')) ?></p></div><div class="record-meta"><span class="badge badge-info"><?= htmlspecialchars((string) ($source['source_type'] ?? '')) ?></span><span><?= htmlspecialchars((string) ($source['version'] ?? '')) ?></span></div></article><?php endforeach; ?></div></section>
<section><div class="section-heading"><div><p class="eyebrow">Traceability</p><h2>Exam intelligence</h2></div></div><div class="record-list"><?php foreach ($signals as $signal): ?><article class="card record-card"><div><strong><?= htmlspecialchars(strtoupper((string) ($signal['exam'] ?? ''))) ?> · <?= htmlspecialchars((string) ($signal['signal_type'] ?? '')) ?></strong><p><?= htmlspecialchars((string) ($signal['notes'] ?? '')) ?></p></div><div class="record-meta"><span class="badge badge-success"><?= htmlspecialchars((string) ($signal['confidence'] ?? '')) ?> confidence</span><span><?= htmlspecialchars((string) ($signal['source_id'] ?? '')) ?></span></div></article><?php endforeach; ?></div></section>
